-- ══════════════════════════════════════════════════════════════════════════════
-- 경사를 음식·카페 장소에도 붙인다 — S15P21E201-1047
-- ══════════════════════════════════════════════════════════════════════════════
--
-- 🔴 왜 이 파일인가. 2026-09-16 운영 실측에서 경사가 이렇게 붙어 있었다.
--
--      출처                 장소 수    경사 붙은 곳
--      관광공사(TOURAPI)        328          327
--      상가정보(SBIZ)          2,355            0
--
--    경사를 만드는 프로그램(bigData/process/place-slope.mjs)이 관광공사 수집본만
--    읽는다. 상가정보 장소는 쳐다보지도 않는다. 그런데 그 2,355곳이 운영 DB 의 88%
--    이고, 추천이 실제로 내놓는 장소의 거의 전부다 — 같은 날 사용자가 만든 2일 8곳
--    일정이 전부 음식점·카페·술집이었다.
--
--    그래서 「완만한 곳만 보기(경사 기준)」를 켜면 사용자가 받는 장소에는 경사 값이
--    하나도 없다. 관광공사 쪽 숫자를 늘려도 이건 안 바뀐다.
--
-- 🔴 「경사 줄이 2,213개인데 327개만 붙었다」는 적재기 잘못이 아니다
--
--    그 2,213줄은 전부 관광공사 장소 번호로 되어 있는데 운영에 있는 관광공사 장소가
--    328곳뿐이다. 즉 붙을 수 있는 것은 전부 붙었다. 나머지 1,886줄은 장소 자체가
--    DB 에 없어서 못 붙는다(그 장소들은 chore/bigData/S15P21E201-1031-detail-refetch
--    가지의 2,217곳 수집본에만 있다). 열쇠가 틀린 것이 아니라 자물쇠가 없는 것이다.
--
--    🔴 그 수집본을 넣어도 추천은 안 늘어난다 — 그중 1,579곳은 관광공사가 분류 코드를
--    안 채워 보내서 갈래가 빈 장소가 되고, 갈래가 빈 장소는 추천 후보에서 언제나
--    빠진다(S15P21E201-899). 숫자만 네 자리가 되고 사용자에게는 아무것도 안 바뀐다.
--    그래서 그 길로 가지 않았다.
--
-- ── 값은 어떻게 나왔나 ──────────────────────────────────────────────────────
--
-- bigData/process/place-slope-sbiz.mjs 가 만든다. 계산 규칙은 기존
-- place-slope.mjs 와 같다 — 반경 200m 안의 보행 구간에서 구간 p50 을 길이로
-- 가중한 p90. 근거는 bigData/docs/PLACE-SLOPE.md 에 있다.
--
-- 🔴 두 프로그램이 같은 규칙을 쓰는지 대조군으로 확인했다. 기존 문서에 적힌 값과
--    소수점까지 같다 — 감천문화마을 16.4% · 마린시티 2.7%(반경 200m 기준).
--    매립지 셋은 5% 아래, 산복도로 셋은 10% 위라는 불변식도 통과했다.
--
-- 🔴 이 값은 ESTIMATED 다. 실측이 아니라 주변 길에서 유도했다. 그리고 방향을 못
--    가른다 — 한쪽만 가파른 장소도 모든 방향을 섞어 잰다. 뜻은 "주변이 얼마나
--    비탈인가" 이지 "가기가 얼마나 힘든가" 가 아니다.
--
-- 🔴 이것은 「휠체어로 갈 수 있다」가 아니다. 경사가 완만해도 입구 계단은 모른다.
--    계단·문턱·엘리베이터는 계산으로 못 만들고, DB 도 그 칸에 추정값을 넣는 것을
--    막는다(ck_place_feature_safety_never_estimated). 화면에 쓸 이름은
--    「완만한 곳만 보기(경사 기준)」다.
--
-- 값 분포 (2355곳):
--   0-4%     750곳
--   4-8%     870곳
--   8-10%    294곳
--   10-15%   284곳
--   15%+     157곳
--
-- 🔴 표본이 모자란 곳은 줄이 아예 없다. 2,356곳 중 1곳이 그랬다 — 반경 200m 안에
--    보행로가 150m 도 없는 자리다. "모른다" 를 "평지" 로 바꿔 적지 않는다.
--
-- ── 값 모양은 채점기가 정한다 ───────────────────────────────────────────────
--
-- 점수형 피처는 value 가 숫자이거나 {"score": …} 여야 읽힌다
-- (BaselineCandidateScorer.extractPlaceScore). 그래서 score 에 담는다 — 다른 이름에
-- 담으면 값이 있는데도 "없음" 으로 읽히고 아무 오류도 안 난다.
-- 옆의 radiusM·segments·walkLengthM 은 채점기가 안 읽지만, 반경을 바꾸면 값이
-- 달라지므로 옛 행과 새 행을 구분할 수 있게 같이 싣는다. 이미 들어가 있는
-- 관광공사 327행과 같은 모양이다.

INSERT INTO place_feature (
    place_feature_id, place_id, feature_type, feature_key, value,
    evidence_status, source_type, source_id, observed_at, source_version, created_at
)
